+  kop[156] = 0x30; // '0': gewoon bestand
+  schrijfTekst(kop, 257, 6, 'ustar\0');
+  schrijfTekst(kop, 263, 2, '00');
+  schrijfTekst(kop, 265, 32, 'root');
+  schrijfTekst(kop, 297, 32, 'root');
