+export function pakUit(items, doel) {
+  for (const { pad, data } of items) {
+    const vol = path.join(doel, ...pad.split('/'));
+    fs.mkdirSync(path.dirname(vol), { recursive: true });
+    fs.writeFileSync(vol, data);
+  }
